export function mergeContacts(existing: Contact[], incoming: Contact[]): Contact[] {
  const result = [...existing];
  // Normalized email -> index in `result`. Keeps the first index for each key, matching the
  // previous findIndex behaviour, and is updated as new contacts are appended so that later
  // duplicates within the same upload still merge into them.
  const indexByEmail = new Map<string, number>();
  for (let i = 0; i < result.length; i++) {
    const key = normalizeEmail(result[i].email);
    if (!indexByEmail.has(key)) indexByEmail.set(key, i);
  }
  for (const contact of incoming) {
    const key = normalizeEmail(contact.email);
    const index = indexByEmail.get(key);
    if (index === undefined) {
      indexByEmail.set(key, result.length);
      result.push(contact);
    } else {
      result[index] = mergeContact(result[index], contact);
    }
  }
  return result;
}

